def fixed_width(n):
    visits = 0
    for row in range(n):
        for column in range(3):
            visits = visits + 1
    return visits

print(fixed_width(7), fixed_width(0))

def positive_report(values):
    positive = 0
    checks = 0
    for value in values:
        checks = checks + 1
        if value > 0:
            positive = positive + 1
    return {"positive": positive, "checks": checks}

report = positive_report([7, -2, 0, 7])
print(report["positive"], report["checks"])
print(positive_report([]))

def loop_counts(n):
    sequential = 0
    for i in range(n):
        sequential = sequential + 1
    for j in range(n):
        sequential = sequential + 1
    square = 0
    for i in range(n):
        for j in range(n):
            square = square + 1
    triangle = 0
    for i in range(n):
        for j in range(i + 1, n):
            triangle = triangle + 1
    return {"sequential": sequential, "square": square, "triangle": triangle}

print(loop_counts(4))
print(loop_counts(0))

def half_steps(n):
    remaining = n
    steps = 0
    while remaining > 1:
        remaining = remaining // 2
        steps = steps + 1
    return steps

for n in [0, 1, 2, 3, 16, 19]:
    print(n, half_steps(n))

